{
  "part": {
    "name": "Bossed mounting arm",
    "description": "A single-piece elongated rectangular arm with a rounded nose, a locally reinforced bulbous transition, and a cylindrical mounting boss containing a coaxial blind bore.",
    "source_views": [
      "front",
      "back",
      "left",
      "right",
      "top",
      "bottom",
      "toprightiso"
    ],
    "symmetry_note": "The complete part is not globally symmetric because the arm extends unequal distances from the boss and has different end profiles. The cylindrical boss is rotationally symmetric about its y-axis, while the boss and transition are locally symmetric about the x=0 plane. The main plate is approximately symmetric about its z=4 thickness mid-plane."
  },
  "Section": [
    {
      "id": "S01",
      "name": "Main arm",
      "features included": [
        "elongated structural spine",
        "constant-thickness rectangular plate",
        "rounded nose",
        "square terminal end",
        "broad load-carrying faces"
      ],
      "function intent": "Provides the principal lever, support, or attachment span and transfers loads between the rounded nose region, the cylindrical mounting interface, and the distant square end.",
      "physical behavior": "The broad plate behaves primarily as a beam. Its width and thickness resist axial load and bending, while its long side faces carry shear. The rounded nose removes a sharp projecting corner and reduces local edge stress.",
      "geometry": "A long, constant-thickness plate extending along the x direction. Most of the planform is rectangular, with a curved left nose generated by a cylindrical edge surface and a flat right end. The front longitudinal edge is interrupted near the boss reinforcement.",
      "location": "Extends across the full length of the part from x=-25 mm to x=80 mm, primarily between y=11 mm and y=23 mm and between z=2 mm and z=6 mm.",
      "colour": {
        "R": 70,
        "G": 130,
        "B": 180
      },
      "major_faces": [
        {
          "face_code": "0000",
          "name": "Rounded nose wall",
          "Brep_id": "FACE 0",
          "description": "Convex cylindrical edge surface forming the rounded left end of the constant-thickness arm."
        },
        {
          "face_code": "0001",
          "name": "Arm lower face",
          "Brep_id": "FACE 1",
          "description": "Large planar underside of the arm at z=2 mm, locally bounded by the boss transition."
        },
        {
          "face_code": "0002",
          "name": "Square terminal face",
          "Brep_id": "FACE 7",
          "description": "Flat vertical end face at x=80 mm closing the remote rectangular end of the arm."
        },
        {
          "face_code": "0003",
          "name": "Front longitudinal wall",
          "Brep_id": "FACE 8",
          "description": "Long planar side wall at y=23 mm extending from the boss-side interruption to the square terminal."
        },
        {
          "face_code": "0004",
          "name": "Arm upper face",
          "Brep_id": "FACE 6",
          "description": "Large planar upper face of the arm at z=6 mm, interrupted locally by the blended boss reinforcement."
        },
        {
          "face_code": "0005",
          "name": "Rear longitudinal wall",
          "Brep_id": "FACE 5",
          "description": "Continuous long planar side wall at y=11 mm spanning the full arm length."
        }
      ],
      "minor_faces_Brep_id": [
        "FACE 2"
      ],
      "relationships": [
        {
          "source id": "S01",
          "target id": "S02",
          "function relationship": "transmits_load, distributes_stress",
          "structural relationship": "attached_to, shares_face, blends_into"
        },
        {
          "source id": "S01",
          "target id": "S03",
          "function relationship": "supports, transmits_load, locates_mating_part",
          "structural relationship": "offset_from, supports"
        }
      ]
    },
    {
      "id": "S02",
      "name": "Boss transition",
      "features included": [
        "bulbous reinforcement",
        "stress-distributing blend",
        "boss support socket",
        "local thickened region"
      ],
      "function intent": "Connects the relatively thin arm to the larger cylindrical boss while avoiding an abrupt section change and supporting the boss against bending or pull-out loads.",
      "physical behavior": "The smoothly curved volume spreads boss loads into a wider area of the arm. Its increased local thickness lowers peak bending and shear stress and reduces the likelihood of cracking at the boss-to-plate junction.",
      "geometry": "A continuous freeform bulbous surface surrounding the base of the boss. It expands radially around the boss axis and blends into the upper, lower, and side regions of the plate near x=0 mm.",
      "location": "Centered near x=0 mm and y=21.5 mm around z=4 mm, between the main arm and the cylindrical boss; it extends approximately from x=-7 mm to x=7 mm, y=19 mm to y=24 mm, and z=-3 mm to z=11 mm.",
      "colour": {
        "R": 230,
        "G": 145,
        "B": 55
      },
      "major_faces": [
        {
          "face_code": "0006",
          "name": "Bulbous transition surface",
          "Brep_id": "FACE 9",
          "description": "Freeform BSpline surface forming the rounded reinforcement and smooth load-spreading blend between the arm and boss."
        }
      ],
      "minor_faces_Brep_id": [],
      "relationships": [
        {
          "source id": "S02",
          "target id": "S01",
          "function relationship": "distributes_stress, transmits_load",
          "structural relationship": "blends_into, attached_to"
        },
        {
          "source id": "S02",
          "target id": "S03",
          "function relationship": "supports, transmits_load, constrains_dof",
          "structural relationship": "attached_to, coaxial_with, blends_into"
        }
      ]
    },
    {
      "id": "S03",
      "name": "Cylindrical mounting boss",
      "features included": [
        "outer cylindrical shell",
        "annular entry rim",
        "coaxial blind bore",
        "planar bore floor",
        "mounting or pivot interface"
      ],
      "function intent": "Provides a cylindrical mounting, locating, or pivot interface for a mating pin, shaft, or cylindrical component. The annular rim supplies an axial seating surface, and the blind bore limits insertion depth.",
      "physical behavior": "The outer wall carries radial bearing and bending loads into the reinforced transition. The inner cylindrical surface locates the mating part and constrains radial translation, while the blind bore floor reacts insertion or axial thrust loads. The annular rim can provide axial registration.",
      "geometry": "A hollow cylindrical boss with an outer radius of 7 mm and a coaxial blind bore of radius 5 mm. The boss axis is parallel to the y direction. Its open end has a planar annular rim at y=34 mm, and the bore terminates at a planar circular floor at y=25 mm.",
      "location": "Centered at x=0 mm and z=4 mm, projecting in the positive y direction from the transition region to y=34 mm.",
      "colour": {
        "R": 85,
        "G": 175,
        "B": 95
      },
      "major_faces": [
        {
          "face_code": "0007",
          "name": "Boss outer cylinder",
          "Brep_id": "FACE 10",
          "description": "Outer cylindrical shell of radius 7 mm forming the load-carrying body of the mounting boss."
        },
        {
          "face_code": "0008",
          "name": "Boss annular rim",
          "Brep_id": "FACE 11",
          "description": "Planar annular end surface at y=34 mm surrounding the blind-bore opening."
        },
        {
          "face_code": "0009",
          "name": "Blind-bore wall",
          "Brep_id": "FACE 3",
          "description": "Coaxial internal cylindrical surface of radius 5 mm that locates an inserted pin or shaft."
        },
        {
          "face_code": "0010",
          "name": "Blind-bore floor",
          "Brep_id": "FACE 4",
          "description": "Planar circular bottom surface at y=25 mm that closes the bore and establishes its insertion depth."
        }
      ],
      "minor_faces_Brep_id": [],
      "relationships": [
        {
          "source id": "S03",
          "target id": "S02",
          "function relationship": "transmits_load, mounts_to, constrains_dof",
          "structural relationship": "attached_to, coaxial_with, supported_by"
        },
        {
          "source id": "S03",
          "target id": "S01",
          "function relationship": "locates_mating_part, transmits_load",
          "structural relationship": "offset_from, supported_by"
        }
      ]
    }
  ]
}
